// ─── R-port catalog (ports.html) + stat tiles (index.html) ──────────────────
// Data source: assets/ports.json, generated by scripts/build_ports.py.
(function () {
  "use strict";

  const PORTS_URL = "assets/ports.json";

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({
      "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
    })[c]);
  }

  function fmtInt(n) {
    return Number(n || 0).toLocaleString("en-US");
  }

  function fmtDate(iso) {
    if (!iso) return "—";
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return "—";
    return d.toISOString().slice(0, 10);
  }

  const STATUS_LABEL = { ported: "Ported", partial: "Partial", planned: "Not yet", skipped: "Skipped" };
  const PARITY_LABEL = { exact: "bit-exact", approx: "≈ tolerance", behavioural: "behavioural", none: "no parity" };
  const PKG_PARITY = {
    pass: { cls: "badge-pass", text: "Parity pass", title: "Port passes its pre-registered parity gate against the R reference" },
    partial: { cls: "badge-partial", text: "Partial", title: "Some outputs match the R reference, some do not yet" },
    gated: { cls: "badge-gate", text: "Gate registered", title: "A pre-registered parity gate (manifest.yaml) exists; result not published in port.yaml" },
    unverified: { cls: "badge-muted", text: "Unverified", title: "No published parity evidence" },
  };

  let cached = null;
  async function loadPorts() {
    if (cached) return cached;
    const res = await fetch(PORTS_URL, { cache: "no-cache" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    cached = await res.json();
    return cached;
  }

  // ─── Stat tiles (ports.html hero + index.html band) ───────────────────────
  function fillStats(data) {
    const s = data.summary || {};
    const pct = s.functions_total ? Math.round((100 * s.functions_ported) / s.functions_total) : 0;
    const values = {
      packages: fmtInt(s.packages),
      python: fmtInt(s.python),
      rust: fmtInt(s.rust),
      functions_total: fmtInt(s.functions_total),
      functions_ported: fmtInt(s.functions_ported),
      ported_pct: `${pct}%`,
      with_parity_gate: fmtInt(s.with_parity_gate),
      with_port_yaml: fmtInt(s.with_port_yaml),
      upstream_cran: fmtInt((s.upstream_sources || {}).CRAN),
      upstream_bioc: fmtInt((s.upstream_sources || {}).Bioconductor),
    };
    document.querySelectorAll("[data-ports-stat]").forEach((el) => {
      const key = el.getAttribute("data-ports-stat");
      if (key in values) el.textContent = values[key];
    });
  }

  // ─── Catalog page ─────────────────────────────────────────────────────────
  const state = { q: "", domain: "all", lang: "all", meta: "all", sort: "name", dir: 1, open: new Set() };

  function packageSearchText(p) {
    const parts = [p.repo, p.pypi, p.import_name, (p.upstream || {}).name, p.domain, p.description];
    (p.functions || []).forEach((f) => {
      parts.push(f.r, f.py);
      (f.aliases || []).forEach((a) => parts.push(a));
    });
    return parts.filter(Boolean).join(" ").toLowerCase();
  }

  function matchesQuery(p, q) {
    if (!q) return true;
    return p._search.includes(q);
  }

  function functionMatches(p, q) {
    if (!q) return [];
    return (p.functions || []).filter((f) =>
      [f.r, f.py, ...(f.aliases || [])].some((x) => x && String(x).toLowerCase().includes(q)),
    );
  }

  function visible(p) {
    if (state.domain !== "all" && p.domain !== state.domain) return false;
    if (state.lang !== "all" && p.lang !== state.lang) return false;
    if (state.meta === "gate" && !["pass", "partial", "gated"].includes((p.parity || {}).status)) return false;
    if (state.meta === "curated" && p.source !== "port.yaml") return false;
    return matchesQuery(p, state.q);
  }

  function sortPackages(list) {
    const key = state.sort;
    const dir = state.dir;
    return list.slice().sort((a, b) => {
      let va; let vb;
      switch (key) {
        case "upstream": va = ((a.upstream || {}).name || "").toLowerCase(); vb = ((b.upstream || {}).name || "").toLowerCase(); break;
        case "domain": va = a.domain || ""; vb = b.domain || ""; break;
        case "functions": va = (a.coverage || {}).total || 0; vb = (b.coverage || {}).total || 0; break;
        case "updated": va = a.pushed_at || ""; vb = b.pushed_at || ""; break;
        default: va = a.repo.toLowerCase(); vb = b.repo.toLowerCase();
      }
      if (va < vb) return -1 * dir;
      if (va > vb) return 1 * dir;
      return a.repo.localeCompare(b.repo);
    });
  }

  function monogram(p) {
    const base = p.repo.replace(/^(py|rust)-/i, "");
    return esc(base.slice(0, 2).toUpperCase());
  }

  function logoCell(p) {
    if (p.logo_url) {
      return `<span class="pt-logo"><img src="${esc(p.logo_url)}" alt="" loading="lazy" data-port-logo /><span class="pt-mono" hidden>${monogram(p)}</span></span>`;
    }
    return `<span class="pt-logo"><span class="pt-mono">${monogram(p)}</span></span>`;
  }

  function parityBadge(p) {
    const st = (p.parity || {}).status || "unverified";
    const b = PKG_PARITY[st] || PKG_PARITY.unverified;
    return `<span class="badge ${b.cls}" title="${esc(b.title)}">${esc(b.text)}</span>`;
  }

  function coverageCell(p) {
    const c = p.coverage || {};
    const total = c.total || 0;
    if (!total) return `<span class="pt-count pt-muted">—</span>`;
    const ported = c.ported || 0;
    const partial = c.partial || 0;
    const pPct = (100 * ported) / total;
    const qPct = (100 * partial) / total;
    const label = p.mapping_quality === "api-only" ? "public API names" : "R → Python";
    return `<span class="pt-bar" aria-hidden="true"><i class="is-ported" style="width:${pPct.toFixed(1)}%"></i><i class="is-partial" style="width:${qPct.toFixed(1)}%"></i></span>
      <span class="pt-count">${fmtInt(ported + partial)} / ${fmtInt(total)}</span>
      <span class="pt-count-label">${esc(label)}</span>`;
  }

  function installLine(p) {
    if (p.lang === "rust" && p.crate && !p.pypi) return `cargo add ${p.crate}`;
    if (p.pypi) return `pip install ${p.pypi}`;
    return null;
  }

  function upstreamCell(p) {
    const u = p.upstream || {};
    const bits = [];
    if (u.source) bits.push(esc(u.source));
    if (u.version) bits.push(`v${esc(u.version)}`);
    if (u.language && u.language !== "R") bits.push(`${esc(u.language)} upstream`);
    const name = u.url
      ? `<a class="pt-upname" href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.name || "—")}</a>`
      : `<span class="pt-upname">${esc(u.name || "—")}</span>`;
    return `${name}<span class="pt-upsrc">${bits.join(" · ") || "&nbsp;"}</span>`;
  }

  function rowHtml(p, domains) {
    const install = installLine(p);
    return `<tr class="port-row" data-repo="${esc(p.repo)}" id="row-${esc(p.repo)}">
      <td class="pt-pkg">
        <button class="pt-toggle" type="button" aria-expanded="${state.open.has(p.repo)}" aria-controls="detail-${esc(p.repo)}">
          ${logoCell(p)}
          <span class="pt-text">
            <span class="pt-name">${esc(p.repo)}${p.source === "port.yaml" ? ' <span class="badge badge-curated" title="Curated from port.yaml">curated</span>' : ' <span class="badge badge-auto" title="Extracted from README / AUDIT.md">auto</span>'}</span>
            <span class="pt-sub">${install ? `<code>${esc(install)}</code>` : esc(p.description || "")}</span>
            <span class="pt-hit" data-hit hidden></span>
          </span>
        </button>
      </td>
      <td class="pt-up">${upstreamCell(p)}</td>
      <td class="pt-domain col-domain">${esc(domains[p.domain] || p.domain || "—")}</td>
      <td class="pt-fn col-fn">${coverageCell(p)}</td>
      <td class="pt-parity col-parity">${parityBadge(p)}</td>
      <td class="pt-updated col-updated">${fmtDate(p.pushed_at)}</td>
    </tr>
    <tr class="port-detail" id="detail-${esc(p.repo)}" ${state.open.has(p.repo) ? "" : "hidden"}>
      <td colspan="6">${state.open.has(p.repo) ? detailHtml(p, domains) : ""}</td>
    </tr>`;
  }

  function dl(label, valueHtml) {
    if (!valueHtml) return "";
    return `<div class="pd-item"><dt>${esc(label)}</dt><dd>${valueHtml}</dd></div>`;
  }

  function functionRows(p) {
    const q = state.q;
    const fns = p.functions || [];
    if (!fns.length) {
      return `<tr><td colspan="4" class="pd-empty">No function mapping published yet. <a href="${esc(p.artifacts && p.artifacts.readme ? p.artifacts.readme : p.html_url)}" target="_blank" rel="noopener">Read the README →</a></td></tr>`;
    }
    const hits = new Set(functionMatches(p, q));
    return fns.map((f) => {
      const hit = q && hits.has(f);
      const dim = q && hits.size && !hit;
      const aliases = (f.aliases || []).length ? `<span class="pd-alias">also ${f.aliases.map((a) => `<code>${esc(a)}</code>`).join(", ")}</span>` : "";
      const parity = f.parity ? `<span class="pd-parity pd-parity-${esc(f.parity)}">${esc(PARITY_LABEL[f.parity] || f.parity)}</span>` : "";
      const test = f.test ? `<span class="pd-test" title="${esc(f.test)}">tested</span>` : "";
      return `<tr class="pd-fn pd-${esc(f.status)}${hit ? " is-hit" : ""}${dim ? " is-dim" : ""}">
        <td class="pd-r">${f.r ? `<code>${esc(f.r)}</code>` : '<span class="pt-muted">— (Python-only)</span>'}</td>
        <td class="pd-py">${f.py ? `<code>${esc(f.py)}</code>` : '<span class="pt-muted">—</span>'}${aliases}</td>
        <td class="pd-status"><span class="pd-dot"></span>${esc(STATUS_LABEL[f.status] || f.status)}${parity}${test}</td>
        <td class="pd-note">${esc(f.note || "")}</td>
      </tr>`;
    }).join("");
  }

  function detailHtml(p, domains) {
    const u = p.upstream || {};
    const par = p.parity || {};
    const art = p.artifacts || {};
    const om = p.omicverse || {};
    const install = installLine(p);
    const c = p.coverage || {};

    const links = [];
    links.push(`<a href="${esc(p.html_url)}" target="_blank" rel="noopener">Repository →</a>`);
    if (p.pypi && p.lang !== "rust") links.push(`<a href="https://pypi.org/project/${esc(p.pypi)}/" target="_blank" rel="noopener">PyPI →</a>`);
    if (art.audit) links.push(`<a href="${esc(art.audit)}" target="_blank" rel="noopener">AUDIT.md →</a>`);
    if (art.report) links.push(`<a href="${esc(art.report)}" target="_blank" rel="noopener">Reconstruction report →</a>`);
    if (art.manifest) links.push(`<a href="${esc(art.manifest)}" target="_blank" rel="noopener">Parity manifest →</a>`);
    if (art.math) links.push(`<a href="${esc(art.math)}" target="_blank" rel="noopener">MATH.md →</a>`);
    (art.notebooks || []).slice(0, 4).forEach((nb) => {
      links.push(`<a href="${esc(nb.url)}" target="_blank" rel="noopener" title="${esc(nb.name)}">${esc(nb.name.replace(/\.ipynb$/, ""))} →</a>`);
    });

    const parityBits = [];
    if (par.algorithm_class) parityBits.push(`class <code>${esc(par.algorithm_class)}</code>`);
    if (par.metric) parityBits.push(`metric <code>${esc(par.metric)}</code>`);
    if (par.threshold != null) parityBits.push(`threshold <code>${esc(par.threshold)}</code>`);
    if (par.value != null) parityBits.push(`value <code>${esc(par.value)}</code>`);
    if (par.fixture) parityBits.push(esc(String(par.fixture).trim()));
    if (par.test) parityBits.push(`<code>${esc(par.test)}</code>`);

    const counts = [
      c.ported ? `${fmtInt(c.ported)} ported` : null,
      c.partial ? `${fmtInt(c.partial)} partial` : null,
      c.planned ? `${fmtInt(c.planned)} not yet` : null,
      c.skipped ? `${fmtInt(c.skipped)} skipped` : null,
    ].filter(Boolean).join(" · ");

    const qualityNote = {
      curated: "Mapping curated by the maintainers in <code>port.yaml</code>.",
      "readme+audit": "Mapping extracted automatically from the README table and <code>AUDIT.md</code>.",
      audit: "Mapping extracted automatically from <code>AUDIT.md</code> (R exports vs Python names).",
      readme: "Mapping extracted automatically from the README table.",
      "api-only": "No R ↔ Python table published yet; showing the package's public Python API (<code>__all__</code>).",
      none: "No mapping information found in the repository yet.",
    }[p.mapping_quality || "none"];

    return `<div class="pd">
      <div class="pd-head">
        <p class="pd-desc">${esc(p.description || "")}</p>
        <div class="pd-links">${links.join("")}</div>
      </div>
      <div class="pd-grid">
        <dl class="pd-meta">
          ${dl("Install", install ? `<code>${esc(install)}</code>` : null)}
          ${dl("Import", p.import_name ? `<code>import ${esc(p.import_name)}</code>` : null)}
          ${dl("Version", p.version ? `<code>${esc(p.version)}</code>` : null)}
          ${dl("Upstream", `${u.url ? `<a href="${esc(u.url)}" target="_blank" rel="noopener">${esc(u.name || "—")}</a>` : esc(u.name || "—")}${u.source ? ` · ${esc(u.source)}` : ""}${u.version ? ` · v${esc(u.version)}` : ""}${u.language && u.language !== "R" ? ` · ${esc(u.language)} upstream` : ""}`)}
          ${dl("Citation", u.citation ? esc(u.citation) : null)}
          ${dl("License", p.license || u.license ? esc(p.license || u.license) : null)}
          ${dl("Domain", esc(domains[p.domain] || p.domain || "—"))}
          ${dl("In omicverse", om.module ? `<code>${esc(om.module)}</code>${om.since ? ` since ${esc(om.since)}` : ""}` : null)}
          ${dl("Parity", `${parityBadge(p)}${parityBits.length ? `<span class="pd-parity-bits">${parityBits.join(" · ")}</span>` : ""}`)}
          ${dl("Coverage", counts || null)}
          ${dl("Tests", art.tests_count ? `${fmtInt(art.tests_count)} test files${art.r_reference_driver ? " · R reference driver" : ""}` : null)}
        </dl>
        <div class="pd-fns">
          <div class="pd-fns-head">
            <span class="pd-fns-title">R ↔ Python function map</span>
            <span class="pd-fns-note">${qualityNote}</span>
          </div>
          <div class="pd-table-wrap">
            <table class="pd-table">
              <thead><tr><th scope="col">R function</th><th scope="col">Python</th><th scope="col">Status</th><th scope="col">Notes</th></tr></thead>
              <tbody>${functionRows(p)}</tbody>
            </table>
          </div>
          ${(p.classes || []).length ? `<div class="pd-classes"><span class="pd-fns-title">Classes</span> ${p.classes.map((k) => `<code>${esc(k.r || "—")}</code> → <code>${esc(k.py || "—")}</code>`).join(" · ")}</div>` : ""}
        </div>
      </div>
      ${p.source !== "port.yaml" ? `<p class="pd-foot">Maintainer of <code>${esc(p.repo)}</code>? Add a <a href="https://github.com/omicverse/omicverse-org-home/blob/main/docs/PORT_MANIFEST.md" target="_blank" rel="noopener"><code>port.yaml</code></a> to replace this auto-extracted row with a curated one.</p>` : ""}
    </div>`;
  }

  function bindLogoFallbacks(root) {
    root.querySelectorAll("img[data-port-logo]").forEach((img) => {
      if (img._bound) return;
      img._bound = true;
      img.addEventListener("error", () => {
        const mono = img.parentElement && img.parentElement.querySelector(".pt-mono");
        img.remove();
        if (mono) mono.hidden = false;
      });
    });
  }

  function render(data) {
    const tbody = document.querySelector("[data-ports-table] tbody");
    const empty = document.querySelector("[data-ports-empty]");
    if (!tbody) return;
    const domains = data.domains || {};
    const q = state.q;
    const list = sortPackages(data.packages.filter(visible));
    tbody.innerHTML = list.map((p) => rowHtml(p, domains)).join("");
    if (empty) empty.hidden = list.length > 0;
    // search hits
    if (q) {
      list.forEach((p) => {
        const hits = functionMatches(p, q);
        const el = tbody.querySelector(`#row-${CSS.escape(p.repo)} [data-hit]`);
        if (!el) return;
        if (hits.length) {
          const names = hits.slice(0, 4).map((f) => `<code>${esc(f.r || f.py)}</code>`).join(", ");
          el.innerHTML = `${hits.length} function${hits.length === 1 ? "" : "s"} match: ${names}${hits.length > 4 ? ", …" : ""}`;
          el.hidden = false;
        }
      });
    }
    bindLogoFallbacks(tbody);
    document.querySelectorAll("[data-sort]").forEach((btn) => {
      const active = btn.dataset.sort === state.sort;
      btn.setAttribute("aria-sort", active ? (state.dir === 1 ? "ascending" : "descending") : "none");
      btn.classList.toggle("active", active);
    });
  }

  function toggle(data, repo, force) {
    const domains = data.domains || {};
    const p = data.packages.find((x) => x.repo === repo);
    if (!p) return;
    const willOpen = force != null ? force : !state.open.has(repo);
    if (willOpen) state.open.add(repo); else state.open.delete(repo);
    const row = document.getElementById(`row-${repo}`);
    const detail = document.getElementById(`detail-${repo}`);
    if (!row || !detail) return;
    row.querySelector(".pt-toggle").setAttribute("aria-expanded", String(willOpen));
    row.classList.toggle("is-open", willOpen);
    if (willOpen) {
      detail.firstElementChild.innerHTML = detailHtml(p, domains);
      detail.hidden = false;
      if (history.replaceState) history.replaceState(null, "", `#${repo}`);
    } else {
      detail.hidden = true;
      detail.firstElementChild.innerHTML = "";
      if (history.replaceState && location.hash === `#${repo}`) history.replaceState(null, "", location.pathname + location.search);
    }
  }

  function buildDomainFilters(data) {
    const holder = document.querySelector("[data-ports-domains]");
    if (!holder) return;
    const counts = {};
    data.packages.forEach((p) => { counts[p.domain] = (counts[p.domain] || 0) + 1; });
    const domains = data.domains || {};
    const ordered = Object.keys(domains).filter((k) => counts[k]);
    Object.keys(counts).forEach((k) => { if (!ordered.includes(k)) ordered.push(k); });
    holder.innerHTML = `<button class="filter active" type="button" data-ports-domain="all">All domains <span class="filter-count">${data.packages.length}</span></button>`
      + ordered.map((k) => `<button class="filter" type="button" data-ports-domain="${esc(k)}">${esc(domains[k] || k)} <span class="filter-count">${counts[k]}</span></button>`).join("");
  }

  function bindControls(data) {
    const search = document.querySelector("[data-ports-search]");
    if (search) {
      let t = null;
      search.addEventListener("input", () => {
        window.clearTimeout(t);
        t = window.setTimeout(() => {
          state.q = search.value.trim().toLowerCase();
          render(data);
        }, 80);
      });
    }
    document.addEventListener("click", (ev) => {
      const domainBtn = ev.target.closest("[data-ports-domain]");
      if (domainBtn) {
        state.domain = domainBtn.dataset.portsDomain;
        document.querySelectorAll("[data-ports-domain]").forEach((b) => b.classList.toggle("active", b === domainBtn));
        render(data);
        return;
      }
      const langBtn = ev.target.closest("[data-ports-lang]");
      if (langBtn) {
        state.lang = langBtn.dataset.portsLang;
        document.querySelectorAll("[data-ports-lang]").forEach((b) => b.classList.toggle("active", b === langBtn));
        render(data);
        return;
      }
      const metaBtn = ev.target.closest("[data-ports-meta]");
      if (metaBtn) {
        state.meta = metaBtn.dataset.portsMeta;
        document.querySelectorAll("[data-ports-meta]").forEach((b) => b.classList.toggle("active", b === metaBtn));
        render(data);
        return;
      }
      const sortBtn = ev.target.closest("[data-sort]");
      if (sortBtn) {
        const key = sortBtn.dataset.sort;
        if (state.sort === key) state.dir = -state.dir;
        else { state.sort = key; state.dir = key === "updated" || key === "functions" ? -1 : 1; }
        render(data);
        return;
      }
      const toggleBtn = ev.target.closest(".pt-toggle");
      if (toggleBtn) {
        const row = toggleBtn.closest(".port-row");
        if (row) toggle(data, row.dataset.repo);
        return;
      }
      const rowCell = ev.target.closest(".port-row td");
      if (rowCell && !ev.target.closest("a")) {
        const row = rowCell.closest(".port-row");
        if (row) toggle(data, row.dataset.repo);
      }
    });
    window.addEventListener("hashchange", () => openFromHash(data));
  }

  function openFromHash(data) {
    const repo = decodeURIComponent(location.hash.replace(/^#/, ""));
    if (!repo) return;
    if (!data.packages.some((p) => p.repo === repo)) return;
    // make sure the row is visible under the current filters
    if (!visible(data.packages.find((p) => p.repo === repo))) {
      state.q = ""; state.domain = "all"; state.lang = "all"; state.meta = "all";
      const search = document.querySelector("[data-ports-search]");
      if (search) search.value = "";
      document.querySelectorAll("[data-ports-domain],[data-ports-lang],[data-ports-meta]").forEach((b) => {
        const v = b.dataset.portsDomain || b.dataset.portsLang || b.dataset.portsMeta;
        b.classList.toggle("active", v === "all");
      });
      render(data);
    }
    toggle(data, repo, true);
    const row = document.getElementById(`row-${repo}`);
    if (row) row.scrollIntoView({ block: "start", behavior: "smooth" });
  }

  // ─── GitHub star count (index + about) ─────────────────────────────────
  async function fillGithubStars() {
    const nodes = document.querySelectorAll("[data-gh-stars]");
    if (!nodes.length) return;
    const key = "gh:stars:omicverse/omicverse";
    let stars = null;
    try { stars = JSON.parse(sessionStorage.getItem(key)); } catch (_) { /* ignore */ }
    if (stars == null) {
      try {
        const res = await fetch("https://api.github.com/repos/omicverse/omicverse", { headers: { Accept: "application/vnd.github+json" } });
        if (res.ok) {
          stars = (await res.json()).stargazers_count;
          try { sessionStorage.setItem(key, JSON.stringify(stars)); } catch (_) { /* quota */ }
        }
      } catch (_) { /* offline / rate-limited: keep the static fallback */ }
    }
    if (typeof stars === "number") {
      const text = stars >= 1000 ? `${(stars / 1000).toFixed(1).replace(/\.0$/, "")}k` : fmtInt(stars);
      nodes.forEach((n) => { n.textContent = text; });
    }
  }

  // ─── Port sticker honeycomb (index) ─────────────────────────────────────
  // Pointy-top hexagons: the sticker's hex occupies 78.9% of the cell width and
  // 91.4% of its height, so neighbours interlock when the horizontal pitch is
  // ~0.80 cell and the vertical pitch ~0.70 cell, with odd rows shifted half a pitch.
  const HEX_W = 0.789, HEX_H = 0.914;
  let wallItems = null;
  let wallResizeBound = false;

  function honeycombLayout(count, width) {
    const cell = width < 480 ? 48 : width < 900 ? 56 : 64;
    const gap = 3;
    const dx = cell * HEX_W + gap;
    const dy = cell * HEX_H * 0.75 + gap * 0.87;
    const cols = Math.max(3, Math.floor((width - cell * (1 - HEX_W)) / dx));
    const rows = [];
    let left = count, r = 0;
    while (left > 0) {
      const cap = r % 2 === 0 ? cols : cols - 1;
      const take = Math.min(cap, left);
      rows.push(take); left -= take; r += 1;
    }
    const positions = [];
    let maxW = 0;
    rows.forEach((n, row) => {
      const off = row % 2 === 0 ? 0 : dx / 2;
      for (let c = 0; c < n; c += 1) positions.push({ x: off + c * dx, y: row * dy });
      maxW = Math.max(maxW, off + (n - 1) * dx + cell);
    });
    const height = rows.length ? (rows.length - 1) * dy + cell : 0;
    return { positions, cell, width: maxW, height };
  }

  function drawHoneycomb(wall) {
    const items = wallItems || [];
    const width = wall.clientWidth || 960;
    const lay = honeycombLayout(items.length, width);
    const offset = Math.max(0, (width - lay.width) / 2);
    wall.style.height = `${lay.height.toFixed(1)}px`;
    wall.innerHTML = items.map((p, i) => {
      const pos = lay.positions[i];
      return `<a href="ports.html#${esc(p.repo)}" title="${esc(p.repo)} · ${esc((p.upstream || {}).name || "")}" aria-label="${esc(p.repo)}" style="left:${(offset + pos.x).toFixed(1)}px;top:${pos.y.toFixed(1)}px;width:${lay.cell}px;height:${lay.cell}px"><img src="${esc(p.logo_url)}" alt="" loading="lazy" data-repo-logo /></a>`;
    }).join("");
    wall.querySelectorAll("img").forEach((img) => {
      img.addEventListener("error", () => {
        // drop the sticker and re-flow once the burst of errors has settled
        const src = img.getAttribute("src");
        wallItems = wallItems.filter((p) => p.logo_url !== src);
        img.closest("a").style.visibility = "hidden";
        window.clearTimeout(drawHoneycomb._t);
        drawHoneycomb._t = window.setTimeout(() => drawHoneycomb(wall), 400);
      });
    });
  }

  function renderLogoWall(data) {
    const wall = document.querySelector("[data-ports-logos]");
    if (!wall) return;
    wallItems = (data.packages || []).filter((p) => p.logo_url);
    drawHoneycomb(wall);
    if (!wallResizeBound) {
      wallResizeBound = true;
      let t = null;
      window.addEventListener("resize", () => {
        window.clearTimeout(t);
        t = window.setTimeout(() => drawHoneycomb(wall), 120);
      });
    }
  }

  async function init() {
    fillGithubStars();
    let data;
    try {
      data = await loadPorts();
    } catch (err) {
      const tbody = document.querySelector("[data-ports-table] tbody");
      if (tbody) tbody.innerHTML = `<tr><td colspan="6"><p class="fetch-error">Couldn't load the port catalog. <a href="https://github.com/omicverse" target="_blank" rel="noopener">View the org on GitHub →</a></p></td></tr>`;
      return;
    }
    data.packages = (data.packages || []).map((p) => ({ ...p, _search: packageSearchText(p) }));
    fillStats(data);
    renderLogoWall(data);
    const foot = document.querySelector("[data-ports-footnote]");
    if (foot && data.generated_at) {
      foot.insertAdjacentHTML("beforeend", ` Last generated <time datetime="${esc(data.generated_at)}">${esc(fmtDate(data.generated_at))}</time>.`);
    }
    if (!document.querySelector("[data-ports-root]")) return;
    buildDomainFilters(data);
    bindControls(data);
    render(data);
    openFromHash(data);
  }

  init();
})();
